import React, { useState, useEffect, useRef } from 'react'
import { chat, getProducts, getProduct } from './api'

export default function App(){
  const [sessionId, setSessionId] = useState(null)
  const [messages, setMessages] = useState([])
  const [input, setInput] = useState('')
  const [suggestions, setSuggestions] = useState([])
  const chatRef = useRef(null)

  useEffect(()=>{ /* greet */
    (async()=>{
      const res = await chat(null, 'hi')
      setSessionId(res.session_id)
      addBotMessage(res.reply)
    })()
  },[])

  function addUserMessage(txt){
    setMessages(m=>[...m, {role:'user', text:txt}])
  }
  function addBotMessage(txt){
    setMessages(m=>[...m, {role:'bot', text:txt}])
  }

  async function handleSend(){
    if(!input.trim()) return
    const msg = input.trim()
    addUserMessage(msg)
    setInput('')
    try{
      const res = await chat(sessionId, msg)
      setSessionId(res.session_id)
      addBotMessage(res.reply)
      setSuggestions(res.suggestions || [])
      // if product object provided, we could render a card - do so by appending a structured bot message
      if(res.product){
        addBotMessage('\n' + JSON.stringify(res.product, null, 2))
      }
      // scroll
      setTimeout(()=>{ if(chatRef.current) chatRef.current.scrollTop = chatRef.current.scrollHeight }, 50)
    }catch(err){
      addBotMessage('Sorry — I could not reach the server. Please try again later.')
    }
  }

  return (
    <div className="app">
      <div className="header"><h2>Lato Chatbot</h2><div style={{marginLeft:'auto'}}>Supportive & friendly — ask about products</div></div>
      <div className="chatbox" ref={chatRef}>
        {messages.map((m,i)=> (
          <div key={i} className={m.role==='user'? 'user':'bot'}>
            <div style={{display:'inline-block',background:m.role==='user'? '#d1f2f0':'#f1f5f9', padding:10, borderRadius:8}}>
              {m.text.split('\n').map((line, idx)=>(<div key={idx}>{line}</div>))}
            </div>
          </div>
        ))}
      </div>

      {suggestions && suggestions.length>0 && (
        <div style={{marginTop:12}}>
          <strong>Suggestions:</strong>
          <div style={{display:'flex', gap:8, flexWrap:'wrap', marginTop:6}}>
            {suggestions.map((s,idx)=>(<button key={idx} onClick={()=>{ setInput(s); }}>{s}</button>))}
          </div>
        </div>
      )}

      <div className="inputRow">
        <input type="text" value={input} onChange={(e)=>setInput(e.target.value)} onKeyDown={(e)=> e.key==='Enter' && handleSend()} placeholder="Ask me about Lato products — e.g. 'show milk'" />
        <button onClick={handleSend}>Send</button>
      </div>
    </div>
  )
}
